// Map schemas to objects
const generateTileMap = (lang: string) => {
    const map: Record<number, string> = {};
    const schema = TILE_SCHEMAS[lang] || TILE_SCHEMAS['en'];
    schema.forEach((name, idx) => {
        map[idx] = name;
    });
    return map;
};

